import{_ as e,o as a,a as r,b as d}from"./app.BGziXukh.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"API列表","link":"/api/SIMD-API/c_api/c_api"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/c_api.md","filePath":"api/SIMD-API/c_api/c_api.md","lastUpdated":1794274609000}'),i={name:"api/SIMD-API/c_api/c_api.md"};function o(c,t,_,p,h,l){return a(),r("div",null,[...t[0]||(t[0]=[d('<div><article class="markdown-body"><h1>API列表</h1><p>C API按功能分为以下类别，点击类别名称可查看对应的概述和API列表。除试验接口外，整体使用时可以包含<code>c_api/asc_simd.h</code>。</p><p>数据搬运接口的概念、硬件通路和选型说明请参见<a href="data_move_guide/data_move_guide.html">数据搬运导览</a>。</p><p><strong>表1</strong> C API分类</p><table><thead><tr><th>类别</th><th>描述</th></tr></thead><tbody><tr><td><a href="defs/overview.html">基础定义</a></td><td>提供C API使用的联合体、枚举、寄存器类型、宏和常量。</td></tr><tr><td><a href="utils/overview.html">工具接口</a></td><td>提供系统初始化、空操作，以及系统资源和变量的访问接口。</td></tr><tr><td><a href="cube_compute/overview.html">矩阵计算</a></td><td>提供矩阵乘加计算及其辅助配置接口。</td></tr><tr><td><a href="cube_datamove/overview.html">矩阵计算搬运</a></td><td>提供矩阵数据搬入、计算结果搬出，以及搬运过程所需的辅助配置接口。</td></tr><tr><td><a href="vector_compute/overview.html">Memory矢量计算</a></td><td>提供基于Unified Buffer（UB）数据的矢量计算接口，涵盖算术、逻辑、归约、广播、比较、排布变换、排序、聚合、类型转换和掩码操作。</td></tr><tr><td><a href="vector_datamove/overview.html">矢量数据搬运</a></td><td>提供Global Memory（GM）、UB和L1 Buffer之间的数据搬运接口，以及填充、多维循环等辅助配置接口。</td></tr><tr><td><a href="reg_compute/overview.html">Reg矢量计算</a></td><td>提供寄存器级矢量计算接口，以及UB与寄存器之间的数据搬运接口，支持自主控制数据搬运和计算过程。</td></tr><tr><td><a href="scalar_compute/overview.html">标量计算</a></td><td>提供标量位运算、类型转换，以及标量数据搬入和搬出接口。</td></tr><tr><td><a href="atomic/overview.html">原子操作</a></td><td>提供数据搬运随路原子操作配置接口，以及对GM中单个元素执行原子计算的标量原子操作接口。</td></tr><tr><td><a href="cache_ctrl/overview.html">缓存控制</a></td><td>提供数据缓存和指令缓存的预加载、失效处理、状态查询，以及标量访存缓存模式配置接口。</td></tr><tr><td><a href="sync/overview.html">同步控制</a></td><td>提供核内流水同步，以及核间、子核间的通知与等待接口。</td></tr><tr><td><a href="experimental/overview.html">试验接口</a></td><td>提供双返回值形式的寄存器计算、数据搬运及指令发射队列状态查询接口。使用时需定义<code>CANN_ASC_USE_EXPERIMENTAL</code>宏，并显式包含对应头文件。</td></tr><tr><td><a href="spr/overview.html">特殊寄存器访问</a></td><td>提供控制寄存器、饱和控制状态与压缩状态的查询和设置接口。</td></tr><tr><td><a href="deprecated_interface/overview.html">废弃接口</a></td><td>汇总已废弃的C API及重载，提供替代接口和迁移说明。</td></tr></tbody></table></article></div>',1)])])}const s=e(i,[["render",o]]);export{v as __pageData,s as default};
